
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_gdme_nv_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_gdme_nv", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([4.988021600451686e+00, 1.528047566867795e+00, -7.681252596676492e-01, -2.214263298388923e+00, -3.017116739443040e+00, -3.309636893341628e+00, -3.177846396207063e+00, -2.685253076505354e+00, -1.896140762041461e+00, -9.049113774595136e-01, -1.802173678794219e-02, -1.925576942280107e-01, -5.620138391361789e-01, -5.093359317966454e-01, -2.887168230148732e-01, -1.526935055738471e-02, 2.913388270801383e-01, 7.935078862204225e-01, 2.473310039722748e+00, 1.381355094048384e+01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


